#!/bin/sh
# SPDX-License-Identifier: GPL-2.0-or-later
# Generates and applies the sandbox egress firewall (nftables). Run as root on the
# Docker host. Idempotent: the Syntaxis tables are replaced, nothing else is touched.
#
#   apply-egress.sh [network-name] [resolver-ip] [extra-blocked-cidr...]
#
# With no arguments it reads SYNTAXIS_SANDBOX_NETWORK and SYNTAXIS_SANDBOX_RESOLVER
# from .env next to docker-compose.yml (defaults: syntaxis-sandbox, 172.30.0.2).
# Addresses in SYNTAXIS_EGRESS_BLOCK (for example your LLM server) are always added.
#
# The rules are generated by `syntaxis egress-rules` from the current .env, using a
# local `syntaxis` binary if there is one, otherwise a throwaway container of the
# Syntaxis image with no network. The installer runs this from a systemd unit at boot,
# whenever Docker starts, when .env changes, and every 15 minutes.
set -eu
cd "$(dirname "$0")/.."
envval() { # value of KEY in .env, or empty
  [ -f .env ] || return 0
  sed -n "s/^$1=//p" .env | tail -n 1
}
NET="${1:-$(envval SYNTAXIS_SANDBOX_NETWORK)}"; NET="${NET:-syntaxis-sandbox}"
RESOLVER="${2:-$(envval SYNTAXIS_SANDBOX_RESOLVER)}"; RESOLVER="${RESOLVER:-172.30.0.2}"
[ $# -ge 2 ] && shift 2 || shift $#

# At boot Docker may still be creating the network: wait for it (up to two minutes).
i=0
until SUBNET=$(docker network inspect "$NET" -f '{{(index .IPAM.Config 0).Subnet}}' 2>/dev/null); do
  i=$((i + 1))
  [ "$i" -ge 60 ] && { echo "network $NET not found; is Syntaxis running?" >&2; exit 1; }
  sleep 2
done
GATEWAY=$(docker network inspect "$NET" -f '{{(index .IPAM.Config 0).Gateway}}')

rules() {
  if command -v syntaxis >/dev/null 2>&1; then
    syntaxis egress-rules "$SUBNET" "$RESOLVER" "$GATEWAY" "$@"
  else
    IMAGE=$(envval SYNTAXIS_IMAGE); IMAGE="${IMAGE:-ghcr.io/kolonuk/syntaxis:latest}"
    set -- "$SUBNET" "$RESOLVER" "$GATEWAY" "$@"
    if [ -f .env ]; then
      docker run --rm --network none --env-file .env "$IMAGE" egress-rules "$@"
    else
      docker run --rm --network none "$IMAGE" egress-rules "$@"
    fi
  fi
}
# generate first, apply only a complete ruleset (nft applies a file atomically)
RS=$(rules "$@")
printf '%s\n' "$RS" | nft -f -
echo "egress rules applied for $NET ($SUBNET)"
